// Extract and format articles for AI scoring
const response = $input.first().json;
const articles = response.articles || [];

return articles.slice(0, 20).map(article => ({
  json: {
    title: article.title || '',
    description: article.description || '',
    url: article.url || '',
    source: article.source?.name || '',
    published_at: article.publishedAt || '',
    content_snippet: (article.content || article.description || '').substring(0, 500)
  }
}));

parameters.text:
=You are a competitive intelligence analyst. Score the following news article on its strategic relevance to {{ $env.ASIS_DEFAULT_COMPANY }} in the {{ $env.ASIS_DEFAULT_SECTOR }} sector.

Article Title: {{ $json.title }}
Source: {{ $json.source }}
Published: {{ $json.published_at }}
Summary: {{ $json.content_snippet }}

Score from 0-10 where:
10 = Direct competitive threat or major strategic opportunity requiring immediate attention
7-9 = Significant market development worth including in strategic brief
4-6 = Moderate relevance, monitor but not urgent
0-3 = Low relevance, routine industry news

Respond with JSON only:
{"relevance_score": <number>, "reasoning": "<1-2 sentences>", "action_required": <true|false>}

parameters.jsCode:
// Parse AI response and attach score to article
const item = $input.first();
let score = 0;
let reasoning = '';
let actionRequired = false;

try {
  const aiText = item.json.output || item.json.text || '{}';
  const cleanText = aiText.replace(/```json?/g, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(cleanText);
  score = parseFloat(parsed.relevance_score || 0);
  reasoning = parsed.reasoning || '';
  actionRequired = parsed.action_required || false;
} catch (e) {
  score = 0;
  reasoning = 'parse_error';
}

return [{
  json: {
    ...item.json,
    relevance_score: score,
    reasoning: reasoning,
    action_required: actionRequired
  }
}];

